insert into public.product_modules select * from jsonb_populate_recordset(null::public.product_modules, '[{"id":"C16QS","technology":"LTE Cat 1bis","peak_downlink_mbps":10,"peak_uplink_mbps":5,"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c16qs","evidence_id":"c16qs-speed"},{"id":"C20QM","technology":"LTE Cat 4","peak_downlink_mbps":150,"peak_uplink_mbps":50,"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c20qm","evidence_id":"c20qm-speed"}]'::jsonb) on conflict (id) do nothing;
insert into public.product_evidence (id,module_id,section,body,tags,source_url) select id,module_id,section,body,tags,source_url from jsonb_populate_recordset(null::public.product_evidence, '[{"id":"c16qs-speed","module_id":"C16QS","section":"Technical Data","body":"C16QS LTE Cat 1bis has published peak speeds of 10 Mbps downlink and 5 Mbps uplink.","tags":["speed","peak","downlink","uplink","throughput","download","upload","lte"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c16qs"},{"id":"c20qm-speed","module_id":"C20QM","section":"Technical Data","body":"C20QM LTE Cat 4 has published peak speeds of 150 Mbps downlink and 50 Mbps uplink.","tags":["speed","peak","downlink","uplink","throughput","download","upload","lte"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c20qm"},{"id":"c16qs-bands","module_id":"C16QS","section":"Technical Data · Cellular Bands","body":"C16QS LTE bands by published region: IN (India) 1, 3, 5, 8, 40, 41; EU 1, 3, 7, 8, 20, 28; NA 2, 4, 5, 12, 25, 66; EAJ 1, 3, 5, 7, 8, 18, 19, 20, 26, 28, 40, 41; AN 1, 3, 5, 8, 18, 19, 26, 28; LA 1, 2, 3, 4, 5, 7, 8; WW 1, 2, 3, 4, 5, 7, 8, 12, 18, 19, 20, 25, 26, 28, 40, 41, 66. Select the exact regional SKU before relying on a band list.","tags":["bands","frequency","region","country","india","europe","north","america","worldwide"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c16qs"},{"id":"c20qm-bands","module_id":"C20QM","section":"Technical Data · Cellular Bands","body":"C20QM published bands: EAJ 1, 3, 5, 7, 8, 18, 19, 20, 26, 28, 38, 40, 41; EU 1, 3, 7, 8, 20, 28; NA 2, 4, 5, 12, 13, 17, 25, 66; AN 1, 3, 5, 8, 18, 19, 26, 28.","tags":["bands","frequency","region","country","europe","north","america"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c20qm"},{"id":"c16qs-esim","module_id":"C16QS","section":"Variants Available for Ordering Samples","body":"Integrated eSIM varies by C16QS SKU. Cavli lists eSIM for C16QS-IN-GNAH, C16QS-NA-GNAH and C16QS-EU-GNAH, and lists no eSIM for C16QS-IN-GNAN, C16QS-NA-GNAN and C16QS-EU-GNAN.","tags":["esim","sim","embedded","integrated","soldered","built-in","remotely"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c16qs"},{"id":"c20qm-esim","module_id":"C20QM","section":"Variants Available for Ordering Samples","body":"C20QM has optional integrated eSIM. Cavli lists C20QM-NA-22GNH with eSIM and C20QM-NA-22GNN without it.","tags":["esim","sim","embedded","integrated","soldered","built-in","remotely"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c20qm"},{"id":"c16qs-gnss","module_id":"C16QS","section":"About · Location services","body":"C16QS offers optional integrated GNSS for GPS and BeiDou. Exact options depend on the SKU.","tags":["gnss","gps","beidou","location","tracking","position","satellite"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c16qs"},{"id":"c20qm-gnss","module_id":"C20QM","section":"About · Location services","body":"C20QM integrates GNSS supporting GPS, GLONASS, BeiDou, Galileo and QZSS.","tags":["gnss","gps","beidou","location","tracking","position","satellite"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c20qm"},{"id":"c16qs-platform","module_id":"C16QS","section":"Technical Data · Platform","body":"C16QS uses FreeRTOS. Cavli lists a 26.5 × 22.5 × 2.3 mm LGA module, three UARTs and USB 2.0.","tags":["os","freertos","package","dimensions","size","usb","uart","lga","interfaces"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c16qs"},{"id":"c20qm-platform","module_id":"C20QM","section":"Technical Data · Platform","body":"C20QM uses Yocto Linux (kernel 4.14). Cavli lists a 37 × 21.8 × 2.8 mm LGA module, three UARTs and high-speed USB.","tags":["os","linux","yocto","package","dimensions","size","usb","uart","lga","interfaces"],"source_url":"https://www.cavliwireless.com/iot-modules/c-series/c20qm"}]'::jsonb) on conflict (id) do nothing;
